package com.vaibhav.ediflow.order.api;

import com.vaibhav.ediflow.order.domain.*; import com.vaibhav.ediflow.order.repository.*; import jakarta.persistence.criteria.Predicate; import org.springframework.data.domain.*; import org.springframework.data.jpa.domain.Specification; import org.springframework.data.web.PageableDefault; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/v1/orders") public class OrderQueryController {
 private final PurchaseOrderRepository orders;private final ProcessingEventRepository events;public OrderQueryController(PurchaseOrderRepository o,ProcessingEventRepository e){orders=o;events=e;}
 @GetMapping @Transactional(readOnly=true) public Page<OrderSummary> list(@RequestParam(required=false)UUID partnerId,@RequestParam(required=false)OrderStatus status,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate from,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate to,@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC)Pageable page){Specification<PurchaseOrder> spec=(root,q,cb)->{List<Predicate> p=new ArrayList<>();if(partnerId!=null)p.add(cb.equal(root.get("partner").get("id"),partnerId));if(status!=null)p.add(cb.equal(root.get("status"),status));if(from!=null)p.add(cb.greaterThanOrEqualTo(root.get("poDate"),from));if(to!=null)p.add(cb.lessThanOrEqualTo(root.get("poDate"),to));return cb.and(p.toArray(Predicate[]::new));};return orders.findAll(spec,page).map(OrderSummary::from);}
 @GetMapping("/{id}") @Transactional(readOnly=true) public OrderDetail get(@PathVariable UUID id){PurchaseOrder o=orders.findById(id).orElseThrow(()->new NotFound("Order not found."));return OrderDetail.from(o,events.findByEntityTypeAndEntityIdOrderByOccurredAt("PURCHASE_ORDER",id));}
 record OrderSummary(UUID id,UUID partnerId,String partnerCode,String poNumber,LocalDate poDate,OrderStatus status,BigDecimal totalAmount,Instant createdAt){static OrderSummary from(PurchaseOrder o){return new OrderSummary(o.getId(),o.getPartner().getId(),o.getPartner().getCode(),o.getPoNumber(),o.getPoDate(),o.getStatus(),o.getTotalAmount(),o.getCreatedAt());}}
 record OrderDetail(UUID id,UUID partnerId,String partnerCode,String poNumber,LocalDate poDate,OrderStatus status,BigDecimal totalAmount,List<Line> lines,List<History> history){static OrderDetail from(PurchaseOrder o,List<ProcessingEvent> h){return new OrderDetail(o.getId(),o.getPartner().getId(),o.getPartner().getCode(),o.getPoNumber(),o.getPoDate(),o.getStatus(),o.getTotalAmount(),o.getLines().stream().map(l->new Line(l.getLineNumber(),l.getSku(),l.getQuantity(),l.getUnitOfMeasure(),l.getUnitPrice(),l.getExtendedPrice())).toList(),h.stream().map(History::from).toList());}}
 record Line(int lineNumber,String sku,BigDecimal quantity,String unitOfMeasure,BigDecimal unitPrice,BigDecimal extendedPrice){} record History(String fromState,String toState,String reason,Instant occurredAt){static History from(ProcessingEvent e){return new History(e.getFromState(),e.getToState(),e.getReason(),e.getOccurredAt());}}
}
